#include <bits/stdc++.h>
using namespace std;

#define ms(s, n) memset(s, n, sizeof(s))
#define FOR(i, a, b) for (int i = (a); i < (b); i++)
#define all(a) (a).begin(), (a).end()
#define pb push_back
#define mp make_pair
typedef long long ll;
typedef vector<int> vi;

inline int bitcount(int x) { return __builtin_popcount(x); }

void transform_array(int arr[], int size, int mod, bool invert) {
    int log_size = __builtin_clz(size) ^ 31;
    for (int i = 0; i < log_size; i++) {
        for (int mask = 0; mask < size; mask++) {
            if (mask & (1 << i)) {
                int prev_mask = mask ^ (1 << i);
                if (!invert) {
                    arr[mask] = (arr[mask] + arr[prev_mask]) % mod;
                } else {
                    arr[mask] = (arr[mask] - arr[prev_mask] + mod) % mod;
                }
            }
        }
    }
}

vector<int> fast_power_convolution(vector<int> a, int k, int p) {
    int n = (int)a.size();
    if (k == 1) return a;
    if (k % 2 == 1) {
        auto temp = fast_power_convolution(a, k - 1, p);
        vector<int> res(n, 0);
        for (int i = 0; i < n; i++) {
            for (int j = 0; j + i < n; j++) {
                res[i + j] = (res[i + j] + (ll)temp[i] * a[j]) % p;
            }
        }
        return res;
    } else {
        auto half = fast_power_convolution(a, k / 2, p);
        vector<int> res(n, 0);
        for (int i = 0; i < n; i++) {
            for (int j = 0; j + i < n; j++) {
                res[i + j] = (res[i + j] + (ll)half[i] * half[j]) % p;
            }
        }
        return res;
    }
}

vector<int> subset_power(vector<int> a, int k, int p) {
    const int LOGN = 19;
    static int fa[LOGN][1 << LOGN], fc[LOGN][1 << LOGN];
    int n = a.size();
    while (n & (n - 1)) n++;
    for (int i = 0; i < LOGN; i++) {
        for (int j = 0; j < n; j++) {
            fa[i][j] = (j < (int)a.size()) ? a[j] : 0;
        }
        transform_array(fa[i], n, p, false);
    }
    for (int i = 0; i < n; i++) {
        vector<int> v(LOGN);
        for (int j = 0; j < LOGN; j++) v[j] = fa[j][i];
        v = fast_power_convolution(v, k, p);
        for (int j = 0; j < LOGN; j++) fc[j][i] = v[j];
    }
    for (int i = 0; i < LOGN; i++) {
        transform_array(fc[i], n, p, true);
    }
    vector<int> result(n, 0);
    for (int j = 0; j < n; j++) {
        int c = bitcount(j);
        if (c < LOGN && j < (int)a.size()) {
            result[j] = fc[c][j];
        }
    }
    return result;
}

const int MAXN = 1e6 + 5;
int n, k, p;
int factorial[MAXN], invFactorial[MAXN];
int f[MAXN];

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    cin >> n >> k >> p;
    int maskVal = 0;
    for (int i = 0; i < 20; i++) {
        if ((n >> i) & 1) maskVal |= (1 << i);
    }
    for (int i = 0; i <= maskVal; i++) {
        int t = 0;
        for (int j = 0; j < 20; j++) {
            if ((n >> j) & 1) {
                t <<= 1;
                t |= (i >> j) & 1;
            }
        }
        f[t] = i;
    }
    if (n & 1) {
        cout << pow(k, n) % p << "\n";
        return 0;
    }
    factorial[0] = 1;
    for (int i = 1; i < MAXN; i++) factorial[i] = (ll)factorial[i - 1] * i % p;
    invFactorial[MAXN - 1] = pow(factorial[MAXN - 1], p - 2, p);
    for (int i = MAXN - 2; i >= 0; i--) invFactorial[i] = (ll)invFactorial[i + 1] * (i + 1) % p;
    vector<int> a(maskVal + 1, 0);
    for (int i = 0; i <= maskVal; i++) a[i] = invFactorial[f[i]];
    int res = pow(k, n) % p;
    a = subset_power(a, k, p);
    int subtractVal = (ll)a[maskVal] * factorial[n] % p;
    res = (res - subtractVal + p) % p;
    cout << res << "\n";
    return 0;
}
